def solve(n, roads):
    parent = list(range(n))
    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u

    def union(u, v):
        pu, pv = find(u), find(v)
        if pu == pv:
            return False
        parent[pu] = pv
        return True

    total_cost = 0
    roads.sort(key=lambda x: x[2])
    for u, v, w in roads:
        if union(u, v):
            total_cost += w
            if n == 1:
                break
    root = find(0)
    for i in range(1, n):
        if find(i) != root:
            return -1
    return total_cost
